<?php
namespace App\Controllers;
use CodeIgniter\Database\BaseConnection;use CodeIgniter\HTTP\ResponseInterface;use Throwable;
class AuditLog extends BaseController{private BaseConnection $db;public function initController($q,$r,$l):void{parent::initController($q,$r,$l);$this->db=db_connect();}public function index():string{return view('pages/audit',['live'=>true,'activeMenu'=>'audit','pageTitle'=>'Audit Log','pageSubtitle'=>'Riwayat perubahan transaksi dan konfigurasi']);}public function read():ResponseInterface{try{$q=$this->db->table('audit_logs al')->select('al.*,u.username,u.full_name')->join('users u','u.id=al.user_id','left');$entity=trim((string)$this->request->getGet('entity'));$action=trim((string)$this->request->getGet('action'));if($entity)$q->where('al.entity_type',$entity);if($action)$q->like('al.action',$action);$rows=$q->orderBy('al.created_at','DESC')->limit(500)->get()->getResultArray();return$this->response->setJSON(['ok'=>true,'data'=>['logs'=>$rows,'entities'=>$this->db->table('audit_logs')->select('entity_type')->distinct()->orderBy('entity_type')->get()->getResultArray()]]);}catch(Throwable $e){return$this->response->setStatusCode(422)->setJSON(['ok'=>false,'message'=>$e->getMessage()]);}}public function detail(int $id):ResponseInterface{$r=$this->db->table('audit_logs al')->select('al.*,u.username,u.full_name')->join('users u','u.id=al.user_id','left')->where('al.id',$id)->get()->getRowArray();return$r?$this->response->setJSON(['ok'=>true,'data'=>$r]):$this->response->setStatusCode(404)->setJSON(['ok'=>false,'message'=>'Audit log tidak ditemukan.']);}}
